<script lang="ts">
  import { onMount } from 'svelte';
  import { accountFetch, bootstrap, type PortalSnapshot } from '$lib/api';

  type Section = 'overview' | 'profile' | 'security' | 'recovery' | 'sessions' | 'apps' | 'passwords' | 'export' | 'lifecycle';
  const sections: { id: Section; label: string; note: string }[] = [
    { id: 'overview', label: 'Overview', note: 'Account pulse' },
    { id: 'profile', label: 'Profile', note: 'Identity & contact' },
    { id: 'security', label: 'Security', note: 'Factors & sign-in' },
    { id: 'recovery', label: 'Recovery', note: 'Your way back in' },
    { id: 'sessions', label: 'Sessions', note: 'Devices & access' },
    { id: 'apps', label: 'Connected apps', note: 'OAuth grants' },
    { id: 'passwords', label: 'App passwords', note: 'Scoped legacy access' },
    { id: 'export', label: 'Export & migrate', note: 'Move your data' },
    { id: 'lifecycle', label: 'Lifecycle', note: 'Pause or leave' }
  ];
  let active: Section = 'overview';
  let snapshot: PortalSnapshot | undefined;
  let loading = true;
  let error = '';
  let notice = '';

  onMount(async () => {
    try {
      await bootstrap();
      snapshot = await accountFetch<PortalSnapshot>('portal');
    } catch (caught) {
      error = caught instanceof Error ? caught.message : 'Sign in to manage this account.';
    } finally { loading = false; }
  });

  function select(section: Section) { active = section; notice = ''; }
  async function revokeOthers() {
    try { await accountFetch('sessions/revoke-others', { method: 'POST', body: '{}' }); notice = 'Other sessions were signed out.'; }
    catch { notice = 'We could not revoke sessions right now.'; }
  }
</script>

<svelte:head>
  <title>Swan / account atlas</title>
  <meta name="description" content="Private account controls for your Swan data server." />
</svelte:head>

<div class="shell">
  <header class="masthead">
    <a class="wordmark" href="/account" aria-label="Swan account home"><span class="mark">✳</span> SWAN <span class="slash">/</span> ACCOUNT ATLAS</a>
    <div class="mast-meta"><span class="eyebrow">PRIVATE CONTROL PLANE</span><span class="rule" aria-hidden="true"></span><span class="status-dot" aria-label="Encrypted connection"></span></div>
  </header>

  {#if loading}
    <main class="loading" aria-live="polite"><span class="spinner" aria-hidden="true"></span><p>Reading your private ledger…</p></main>
  {:else if error}
    <main class="empty-state" aria-labelledby="sign-in-title"><p class="eyebrow">ACCOUNT ATLAS</p><h1 id="sign-in-title">A quiet place for your data.</h1><p>{error}</p><a class="button primary" href="/oauth/authorize">Sign in securely <span>↗</span></a></main>
  {:else if snapshot}
    <div class="layout">
      <aside class="sidebar" aria-label="Account sections">
        <div class="account-chip"><div class="avatar">{snapshot.account.handle.slice(0, 1).toUpperCase()}</div><div><strong>@{snapshot.account.handle}</strong><small>{snapshot.account.did}</small></div></div>
        <nav>{#each sections as section, i}<button class:active={active === section.id} on:click={() => select(section.id)}><span class="nav-index">{String(i + 1).padStart(2, '0')}</span><span>{section.label}</span><small>{section.note}</small></button>{/each}</nav>
        <div class="sidebar-foot"><span class="status-dot"></span><span>Encrypted at rest</span><span class="version">v1.0</span></div>
      </aside>

      <main class="content" aria-live="polite">
        <div class="content-head"><div><p class="eyebrow">{active === 'overview' ? 'WELCOME BACK' : sections.find((section) => section.id === active)?.note.toUpperCase()}</p><h1>{sections.find((section) => section.id === active)?.label}</h1></div><div class="head-actions"><span class="last-seen">Last checked just now</span><button class="icon-button" aria-label="Account menu">•••</button></div></div>
        {#if notice}<div class="notice" role="status">{notice}</div>{/if}

        {#if active === 'overview'}
          <section class="hero-grid"><article class="hero-card"><div><p class="eyebrow pale">YOUR DATA, YOUR RULES</p><h2>Everything is<br /><em>in your hands.</em></h2><p class="hero-copy">A calm view of the credentials, identities, and devices that touch your personal data server.</p></div><div class="hero-glyph" aria-hidden="true">✳</div></article><article class="signal-card"><span class="eyebrow">ACCOUNT SIGNAL</span><div class="signal-value"><span class="status-dot"></span>Clear</div><p>No unusual activity detected.</p><div class="signal-line"><span style="width: 82%"></span></div><small>Protected by your management session</small></article></section>
          <section class="metric-grid"><article><span class="metric-label">IDENTITY</span><strong>{snapshot.identity?.method === 'didWeb' ? 'did:web' : 'PLC'}</strong><span class="metric-note">{snapshot.identity?.state ?? 'Pending verification'}</span></article><article><span class="metric-label">ACTIVE DEVICES</span><strong>{snapshot.sessions.length}</strong><span class="metric-note">Across your account</span></article><article><span class="metric-label">CONNECTED APPS</span><strong>{snapshot.apps.length}</strong><span class="metric-note">OAuth access grants</span></article><article><span class="metric-label">ACCOUNT AGE</span><strong>—</strong><span class="metric-note">Private by default</span></article></section>
          <section class="split"><article class="panel"><div class="panel-head"><div><span class="eyebrow">IDENTITY</span><h2>How the world finds you</h2></div><button class="text-button" on:click={() => select('profile')}>Manage ↗</button></div><div class="identity-row"><div class="identity-symbol">{snapshot.identity?.method === 'didWeb' ? '◎' : '◇'}</div><div><strong>@{snapshot.account.handle}</strong><p>{snapshot.account.did}</p></div><span class="pill success">Verified</span></div></article><article class="panel warm"><div class="panel-head"><div><span class="eyebrow">NEXT BEST STEP</span><h2>Review your sessions</h2></div><span class="arrow">↗</span></div><p class="panel-copy">Keep only the devices you recognize. Revoking a session is immediate and reversible by signing in again.</p><button class="button dark" on:click={() => select('sessions')}>Review devices</button></article></section>
        {:else if active === 'sessions'}
          <section class="panel"><div class="panel-head"><div><span class="eyebrow">DEVICES & ACCESS</span><h2>Where you’re signed in</h2></div><button class="button danger-outline" on:click={revokeOthers}>Sign out others</button></div><div class="table">{#each snapshot.sessions as session}<div class="table-row"><div class="device-icon">{session.kind === 'management' ? '⌂' : '◌'}</div><div><strong>{session.label}{#if session.current}<span class="current">CURRENT</span>{/if}</strong><small>{session.kind} · Last seen {session.lastSeen}</small></div><button class="row-action" aria-label={`Revoke ${session.label}`}>Revoke</button></div>{/each}</div></section>
        {:else if active === 'passwords'}
          <section class="panel"><div class="panel-head"><div><span class="eyebrow">SCOPED LEGACY ACCESS</span><h2>App passwords</h2></div><button class="button primary">Create password <span>＋</span></button></div><p class="panel-copy">Use these only for clients that cannot use OAuth. Each secret is shown once, never stored in your browser, and can be scoped to the minimum access it needs.</p><div class="table">{#if snapshot.passwords.length === 0}<div class="empty-row">No app passwords yet. That’s a good default.</div>{:else}{#each snapshot.passwords as password}<div class="table-row"><div class="device-icon">⌁</div><div><strong>{password.name}</strong><small>{password.scopes.join(' · ')}</small></div><button class="row-action">Revoke</button></div>{/each}{/if}</div></section>
        {:else if active === 'apps'}
          <section class="panel"><div class="panel-head"><div><span class="eyebrow">OAUTH GRANTS</span><h2>Connected apps</h2></div></div><p class="panel-copy">These apps can act on your behalf through narrowly scoped, DPoP-bound grants. Revocation takes effect immediately.</p><div class="table">{#if snapshot.apps.length === 0}<div class="empty-row">No connected apps. Your account is quiet.</div>{:else}{#each snapshot.apps as app}<div class="table-row"><div class="app-badge">{app.name.slice(0, 1)}</div><div><strong>{app.name}</strong><small>{app.scopes.join(' · ')}</small></div><button class="row-action">Revoke</button></div>{/each}{/if}</div></section>
        {:else}
          <section class="panel prose"><span class="eyebrow">{sections.find((section) => section.id === active)?.note.toUpperCase()}</span><h2>{active === 'profile' ? 'Your public identity, clearly held.' : active === 'security' ? 'Keep sign-in decisions close.' : active === 'recovery' ? 'Make the way back deliberate.' : active === 'export' ? 'Take a portable copy of your data.' : active === 'lifecycle' ? 'Pause or leave on your terms.' : 'A focused control for your account.'}</h2><p>{active === 'profile' ? `@${snapshot.account.handle} is the handle currently attached to ${snapshot.account.did}.` : active === 'security' ? `${snapshot.factors.length} authentication factor${snapshot.factors.length === 1 ? '' : 's'} are registered for this account.` : active === 'recovery' ? 'Recovery codes are generated once and should be stored offline, away from this browser.' : active === 'export' ? 'Prepare an export request and the server will report its status without placing private data in the page.' : active === 'lifecycle' ? 'Lifecycle changes are deliberate, authenticated actions and cannot be triggered by a cross-site request.' : 'This control is capability-aware and reports unavailable operations without exposing private details.'}</p><div class="capability-note"><span>✦</span><div><strong>Protected action</strong><small>Mutations require same-origin JSON, a fresh CSRF token, and the appropriate step-up.</small></div></div>{#if active === 'export'}<button class="button primary" on:click={() => accountFetch('export/request', { method: 'POST', body: '{}' }).then(() => notice = 'Export request accepted.').catch(() => notice = 'Export is not available right now.')}>Request export ↗</button>{:else if active === 'recovery'}<button class="button primary" on:click={() => accountFetch('factors/recovery-codes/rotate', { method: 'POST', body: '{}' }).then(() => notice = 'Recovery codes rotated.').catch(() => notice = 'Recovery rotation is not available right now.')}>Rotate recovery codes ↗</button>{:else if active === 'lifecycle'}<button class="button danger-outline" on:click={() => accountFetch('lifecycle/delete', { method: 'POST', body: '{}' }).then(() => notice = 'Lifecycle request accepted.').catch(() => notice = 'Lifecycle changes require additional verification.')}>Request account closure</button>{/if}</section>
        {/if}
      </main>
    </div>
  {/if}
  <footer class="footer"><span>SWAN ACCOUNT ATLAS</span><span>Local-first. Open protocol. Quietly yours.</span><span>Privacy ↗</span></footer>
</div>

