e) }.table-row { display:flex; align-items:center; gap:14px; min-height:74px; border-bottom:1px solid var(--line) }.table-row strong { font-size:13px; display:block }.table-row small { color:var(--muted); display:block; font:10px var(--mono); margin-top:5px }.row-action { margin-left:auto; border:0; background:none; color:var(--coral); font:10px var(--mono) }.current { color:var(--teal); background:#dceee1 }.app-badge { width:37px; height:37px; display:grid; place-items:center; color:white; background:var(--ochre); font:700 17px var(--serif) }.empty-row { color:var(--muted); font-size:13px; padding:23px 0 }.prose { max-width:700px; min-height:310px }.prose h2 { font-size:39px; margin-top:45px; max-width:480px }.prose p { color:var(--muted); line-height:1.7; max-width:550px }.capability-note { display:flex; gap:12px; margin-top:38px; padding:15px; background:#eee9dc; max-width:550px }.capability-note > span { color:var(--ochre); font-size:22px }.capability-note strong,.capability-note small { display:block }.capability-note small { color:var(--muted); font-size:11px; margin-top:4px }.notice { color:var(--teal-deep); background:#dceee1; padding:10px 14px; font-size:12px; margin:-15px 0 20px }.loading,.empty-state { min-height:calc(100vh - 180px); display:grid; place-content:center; text-align:center }.spinner { width:30px; height:30px; border:2px solid var(--line); border-top-color:var(--teal); border-radius:50%; animation:spin 1s linear infinite; margin:auto }.loading p { color:var(--muted); font:12px var(--mono) }.empty-state h1 { font:400 52px var(--serif); margin:16px 0 }.empty-state p:not(.eyebrow) { color:var(--muted); max-width:360px; line-height:1.6; margin:0 auto 25px }.footer { border-top:1px solid var(--line); height:60px; display:flex; justify-content:space-between; align-items:center; color:var(--muted); font:10px var(--mono); letter-spacing:.04em }.footer span:nth-child(2) { font-family:var(--serif); font-size:12px; font-style:italic }.footer span:last-c